class DeltaAggregator:
    def __init__(self): self.buf = ConcurrentMap()
    def add(self, key, d): self.buf.merge(key, d, operator.add)
    def flush_loop(self):
        while True:
            sleep(1.0)
            old, self.buf = self.buf, ConcurrentMap()   # atomic swap
            batch = [(k, v) for k, v in old.items() if v != 0]
            for k, v in batch:
                s = shard_selector.pick(k)                 # 0 for cold keys
                kafka.send('counter-deltas', key=f'{k}#{s}', value=v)
            kafka.flush()

W, D = 2**16, 4
cms = [[0]*W for _ in range(D)]
def observe(key):
    est = min(cms[i][h_i(key) % W] for i in range(D))
    for i in range(D): cms[i][h_i(key) % W] += 1
    heap.update(key, est + 1)                  # keep top 1000
def every_second():
    for k, est in heap.items():
        if est > 1000: report_hot(k, est)
    decay(cms, factor=0.5)

def shards_for(rate):
    return min(256, next_pow2(ceil(rate / 5000)))   # <= 5k writes/s per shard

def rollup_loop():
    while True:
        keys = dirty_keys.drain()           # from writers
        for k in keys:
            n = config.shards(k)
            total = sum(store.get(k, s) for s in range(n_max_seen(k)))
            store.put_total(k, total, now())
            redis.set(f'total:{k}', total, ex=5)
        sleep(1.0)
